<?php

namespace App\Models;

use Illuminate\Database\Eloquent\Model;
use Illuminate\Database\Eloquent\Relations\BelongsTo;

class PromptEmbedding extends Model
{
    /**
     * The table name is stated explicitly because the primary key is not `id`.
     *
     * @var string
     */
    protected $table = 'prompt_embeddings';

    /**
     * prompt_id is the primary key: one current embedding per prompt.
     *
     * @var string
     */
    protected $primaryKey = 'prompt_id';

    /**
     * The primary key is supplied by the prompt, not generated by the table.
     *
     * @var bool
     */
    public $incrementing = false;

    /**
     * @var string
     */
    protected $keyType = 'int';

    /**
     * Every column here is produced by the embedding service, never by user
     * input.
     *
     * Under MariaDB `vector_json` is stored as LONGTEXT with a JSON_VALID
     * check, so the `array` cast below handles encode/decode in PHP.
     *
     * @var list<string>
     */
    protected $fillable = [
        'prompt_id',
        'provider',
        'model_name',
        'dimensions',
        'vector_json',
        'content_hash',
    ];

    /**
     * @return array<string, string>
     */
    protected function casts(): array
    {
        return [
            'vector_json' => 'array',
            'dimensions' => 'integer',
        ];
    }

    /**
     * @return BelongsTo<Prompt, $this>
     */
    public function prompt(): BelongsTo
    {
        return $this->belongsTo(Prompt::class);
    }
}
